
  create view "postgres"."dbt"."stg_link_customer_order__dbt_tmp" as (
    





with staging as (
    -- Generated by AutomateDV (formerly known as dbtvault)

    

WITH source_data AS (

    SELECT

    order_key,
    customer_key,
    customer_pk,
    order_pk

    FROM "postgres"."dbt"."stg_customer_order"
),

derived_columns AS (

    SELECT

    order_key,
    customer_key,
    customer_pk,
    order_pk,
    'CSV_CUSTOMERS'::TEXT AS RECORD_SOURCE

    FROM source_data
),

hashed_columns AS (

    SELECT

    order_key,
    customer_key,
    customer_pk,
    order_pk,
    RECORD_SOURCE,

    DECODE(MD5(NULLIF(CONCAT(
        COALESCE(NULLIF(UPPER(TRIM(CAST(ORDER_KEY AS VARCHAR))), ''), '^^'), '||',
        COALESCE(NULLIF(UPPER(TRIM(CAST(CUSTOMER_KEY AS VARCHAR))), ''), '^^')
    ), '^^||^^')), 'hex') AS LINK_CUSTOMER_ORDER_PK

    FROM derived_columns
),

columns_to_select AS (

    SELECT

    order_key,
    customer_key,
    customer_pk,
    order_pk,
    RECORD_SOURCE,
    LINK_CUSTOMER_ORDER_PK

    FROM hashed_columns
)

SELECT * FROM columns_to_select
)

select *, current_timestamp as LOAD_DATE,
    current_timestamp AS EFFECTIVE_FROM from staging
  );